function demoMain(idx,label){
  var fns=[[["add","Adds two numbers.","a,b"],["sub","Subtracts b from a.","a,b"]],[["greet","Returns a greeting.","name"],["bye","Returns a farewell.","name"]],[["parse","Parses input text.","text"],["render","Renders output.","doc"]]];
  var f=fns[idx%fns.length]; var md=f.map(function(x){return "### "+x[0]+"("+x[2]+")\n"+x[1];}).join("\n");
  return "["+label+"] generated docs for "+f.length+" functions:\n"+md;
}

